// Minimal Modbus TCP read (FC4 input / FC3 holding) — read-only discovery
const host = "192.168.68.57", port = 502;
function frame(tid: number, unit: number, fc: number, addr: number, qty: number) {
  const b = Buffer.alloc(12);
  b.writeUInt16BE(tid, 0); b.writeUInt16BE(0, 2); b.writeUInt16BE(6, 4);
  b.writeUInt8(unit, 6); b.writeUInt8(fc, 7); b.writeUInt16BE(addr, 8); b.writeUInt16BE(qty, 10);
  return b;
}
async function read(unit: number, fc: number, reg1based: number, qty: number): Promise<number[] | string> {
  return new Promise((resolve) => {
    let buf = Buffer.alloc(0);
    const t = setTimeout(() => { sock?.end(); resolve("timeout"); }, 4000);
    let sock: any;
    Bun.connect({ hostname: host, port, socket: {
      open(s) { sock = s; s.write(frame(1, unit, fc, reg1based - 1, qty)); },
      data(s, d) { buf = Buffer.concat([buf, d]);
        if (buf.length >= 9) { const fcR = buf[7];
          if (fcR & 0x80) { clearTimeout(t); s.end(); resolve(`exception 0x${buf[8].toString(16)}`); return; }
          const n = buf[8]; if (buf.length >= 9 + n) { clearTimeout(t); s.end();
            const out: number[] = []; for (let i = 0; i < n / 2; i++) out.push(buf.readUInt16BE(9 + i * 2)); resolve(out); } } },
      error(s, e) { clearTimeout(t); resolve("err " + e.message); }, close() {} } });
  });
}
const s32 = (r: number[], i: number) => { const v = (r[i+1] << 16) | r[i]; return v > 0x7fffffff ? v - 0x100000000 : v; }; // Sungrow little-endian word order
const u32 = (r: number[], i: number) => ((r[i+1] << 16) | r[i]) >>> 0;
for (const unit of [1]) {
  console.log("unit", unit);
  const a = await read(unit, 4, 5000, 30); console.log("5000-5029 (device type@5000, nominal power@5001, ...):", a);
  if (Array.isArray(a)) { console.log("device_type_code: 0x" + a[0].toString(16), "nominal_kW:", a[1]/10, "daily_pv_kWh:", a[3]/10, "total_pv_kWh(u32@5004):", u32(a,4)/1); }
  const sn = await read(unit, 4, 4990, 10); if (Array.isArray(sn)) console.log("serial:", Buffer.from(sn.flatMap(w=>[w>>8, w&0xff])).toString("ascii").replace(/\0/g,""));
  const b = await read(unit, 4, 5080, 20); console.log("5080-5099 (SG: 5083 export power s32, 5091 meter power s32?):", b);
  if (Array.isArray(b)) console.log("  5083 export_power_W(s32):", s32(b,3), " 5091(s32):", s32(b,11), " 5097(s32):", s32(b,17));
  const c = await read(unit, 4, 5600, 40); console.log("5600-5639 (SH: 5600 meter active power s32, 5602 meter phase...):", c);
  if (Array.isArray(c)) console.log("  5600 meter_power_W(s32):", s32(c,0));
  const d = await read(unit, 4, 13000, 40); console.log("13000-13039 (SH: 13008 load power s32, 13010 export power s32, 13022 batt...):", d);
  if (Array.isArray(d)) console.log("  13008 load_W:", s32(d,7), " 13010 export_W:", s32(d,9), " 13022 batt_level%:", d[21]/10, " 13001 running_state:", d[0]);
  const e = await read(unit, 3, 5000, 10); console.log("holding 5000-5009 (SG string inverters, e.g. 5006 start/stop):", e);
}
